if (docs.length !== 3) fail('error: expected three parts separated by %%%')
const [mine, base, theirs] = docs

function changes(x, y) {
  const n = x.length, m = y.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--)
    L[i][j] = x[i] === y[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const out = []
  let i = 0, j = 0, bi = 0, bj = 0
  const flush = () => { if (i > bi || j > bj) out.push({ bs: bi, be: i, ss: bj, se: j }) }
  while (i < n || j < m) {
    if (i < n && j < m && x[i] === y[j]) { flush(); i++; j++; bi = i; bj = j }
    else if (i < n && (j >= m || L[i + 1][j] >= L[i][j + 1])) i++
    else j++
  }
  flush()
  return out
}

const all = [
  ...changes(base, mine).map(c => ({ ...c, side: 0 })),
  ...changes(base, theirs).map(c => ({ ...c, side: 1 })),
].sort((a, b) => a.bs - b.bs || a.side - b.side)

const sides = [mine, theirs]
const out = []
const eq = (a, b) => a.length === b.length && a.every((v, i) => v === b[i])
let pos = 0, k = 0
while (k < all.length) {
  if (all[k].bs > pos) { const s = base.slice(pos, all[k].bs); out.push({ t: 'stable', lines: s }); pos = all[k].bs }
  const rs = all[k].bs
  let re = all[k].be
  const group = [all[k++]]
  while (k < all.length && all[k].bs <= re) { re = Math.max(re, all[k].be); group.push(all[k++]) }
  const baseL = base.slice(rs, re)
  if (group.length === 1) {
    const c = group[0]
    out.push({ t: c.side ? 'theirs' : 'mine', lines: sides[c.side].slice(c.ss, c.se) })
  } else {
    const rep = [0, 1].map(s => {
      const g = group.filter(c => c.side === s)
      if (!g.length) return baseL
      const lo = Math.min(...g.map(c => c.ss - (c.bs - rs)))
      const hi = Math.max(...g.map(c => c.se + (re - c.be)))
      return sides[s].slice(lo, hi)
    })
    const [m, t] = rep
    if (eq(m, t)) out.push({ t: 'both', lines: m })
    else if (eq(m, baseL)) out.push({ t: 'theirs', lines: t })
    else if (eq(t, baseL)) out.push({ t: 'mine', lines: m })
    else out.push({ t: 'conflict', m, b: baseL, th: t })
  }
  pos = re
}
if (pos < base.length) out.push({ t: 'stable', lines: base.slice(pos) })

const res = []
let conflict = false
for (const r of out) {
  if (r.t === 'conflict') {
    conflict = true
    if (mode === 'regions') res.push(`conflict mine=${r.m.length} base=${r.b.length} theirs=${r.th.length}`)
    else {
      res.push('<<<<<<< mine', ...r.m)
      if (mode === 'merge') res.push('||||||| base', ...r.b)
      res.push('=======', ...r.th, '>>>>>>> theirs')
    }
  } else if (mode === 'regions') res.push(`${r.t} ${r.lines.length}`)
  else res.push(...r.lines)
}
process.stdout.write(res.map(l => l + '\n').join(''))
process.exitCode = conflict ? 1 : 0
